import hmac
import json

from payhook.errors import InvalidNotification

MAX_TIMESTAMP_DELTA = 300


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    # Parse JSON body
    try:
        data = json.loads(raw_body.decode("utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification("Invalid JSON body")

    # Validate required fields
    event_id = data.get("event_id")
    account_id = data.get("account_id")
    amount_minor = data.get("amount_minor")
    currency = data.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("Invalid or missing event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("Invalid or missing account_id")
    if not isinstance(amount_minor, int) or isinstance(amount_minor, bool) or amount_minor < 0:
        raise InvalidNotification("Invalid or missing amount_minor")
    if not isinstance(currency, str) or len(currency) != 3 or not currency.isascii() or not currency.isupper():
        raise InvalidNotification("Invalid or missing currency")

    # Validate timestamp
    timestamp = headers.get("X-Pay-Timestamp")
    if not timestamp:
        raise InvalidNotification("Missing X-Pay-Timestamp")
    try:
        ts_int = int(timestamp)
    except ValueError:
        raise InvalidNotification("Invalid X-Pay-Timestamp")
    if abs(ts_int - now) > MAX_TIMESTAMP_DELTA:
        raise InvalidNotification("Timestamp outside acceptable window")

    # Validate signature (v1 path)
    signature = headers.get("X-Pay-Signature", "")
    if signature.startswith("v1="):
        expected_digest = hmac.new(
            secret, timestamp.encode("ascii") + b"." + raw_body,
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature[3:], expected_digest):
            # v1 present but doesn't match - try v0 receipt path
            pass
        else:
            return {
                "event_id": event_id,
                "account_id": account_id,
                "amount_minor": amount_minor,
                "currency": currency,
            }

    # Validate v0 receipt (legacy migration path)
    receipt = headers.get("X-Pay-Receipt", "")
    if receipt.startswith("r0="):
        receipt_payload = timestamp.encode("ascii") + b"." + event_id.encode("utf-8")
        expected_receipt = hmac.new(secret, receipt_payload, hashlib.sha256).hexdigest()
        if hmac.compare_digest(receipt[3:], expected_receipt):
            return {
                "event_id": event_id,
                "account_id": account_id,
                "amount_minor": amount_minor,
                "currency": currency,
            }

    raise InvalidNotification("Signature or receipt verification failed")"}]}
